// SELECT: 'ALL' runs all 9 test events, or choose one: order_created | low_inventory | customer_message |
// return_requested | cart_abandoned | competitor_price_changed | negative_review_detected | sales_anomaly | daily_business_review
const SELECT = 'ALL';
// Set true to send every event twice and watch the idempotency / duplicate path
const SEND_DUPLICATES = false;
const T = {
 order_created: {eventType:'order_created', source:'shopify', customerId:'C-2001', orderId:'O-5001', sku:'WEB-PRO-BLK', productId:'P-1001',
   payload:{total:149.97, currency:'USD', paymentStatus:'PAID', items:[{sku:'WEB-PRO-BLK', qty:3, price:49.99}]}},
 low_inventory: {eventType:'low_inventory', source:'amazon', sku:'WEB-PRO-BLK', productId:'P-1001',
   payload:{currentStock:140, threshold:400, marketplace:'amazon'}},
 customer_message: {eventType:'customer_message', source:'generic', customerId:'C-2001',
   payload:{channel:'email', message:'Hi, where is my order O-5003? It was supposed to arrive yesterday.'}},
 return_requested: {eventType:'return_requested', source:'shopify', customerId:'C-2002', orderId:'O-5002',
   payload:{reason:'Changed my mind', condition:'unopened', requestedResolution:'refund', refundAmount:24.99}},
 cart_abandoned: {eventType:'cart_abandoned', source:'shopify', customerId:'C-2003',
   payload:{cartValue:129.9, minutesSinceAbandon:95, consent:{email:true, sms:false}, items:[{sku:'WEB-PRO-BLK', qty:2, price:49.99},{sku:'EAR-TIPS-SET', qty:1, price:29.92}]}},
 competitor_price_changed: {eventType:'competitor_price_changed', source:'amazon', sku:'YOGA-MAT-PRM', productId:'P-1003',
   payload:{competitor:'Seller-X', previousCompetitorPrice:31.49, competitorPrice:27.49}},
 negative_review_detected: {eventType:'negative_review_detected', source:'amazon', sku:'WEB-PRO-BLK', productId:'P-1001',
   payload:{reviewId:'R-9001', rating:1, text:'Battery died after two days and support never replied. Very disappointed.'}},
 sales_anomaly: {eventType:'sales_anomaly', source:'generic',
   payload:{metric:'revenue', period:'today', question:'Why did sales fall?'}},
 daily_business_review: {eventType:'daily_business_review', source:'generic',
   payload:{question:'What needs my attention today?'}}
};
const now = new Date().toISOString();
const keys = SELECT === 'ALL' ? Object.keys(T) : [SELECT];
const out = [];
for (const k of keys) {
  const ev = {...T[k], eventId:'test-' + k + '-001', timestamp: now};
  out.push({json: ev});
  if (SEND_DUPLICATES) out.push({json: {...ev}});
}
return out;

const d = new Date();
const day = d.toISOString().slice(0,10);
const out = [{json:{eventType:'daily_business_review', source:'schedule', eventId:'daily-' + day, timestamp:d.toISOString(), payload:{question:'What needs my attention today?'}}}];
if (d.getUTCDay() === 1) out.push({json:{eventType:'weekly_business_review', source:'schedule', eventId:'weekly-' + day, timestamp:d.toISOString(), payload:{question:'How did the week go?'}}});
return out;

// ====== CENTRAL CONFIG (edit here) ======
const CONFIG = {
  aiEnabled: false,                 // true => agents call the LLM node; false => deterministic rules only (works with no credentials)
  aiModel: 'REPLACE_WITH_MODEL_NAME',
  dryRun: true,                     // true => no external API call is ever made; actions are only simulated and logged
  simulateApproval: false,          // true => test mode auto-approves pending approvals so you can see execution end-to-end
  lowConfidenceThreshold: 0.6,      // below this, non-passive actions go to human approval
  maxAutoDiscountPct: 10,           // larger discounts always need approval
  autoApproveReturns: false,        // financial actions need approval by default
  highValueOrderThreshold: 500,
  idempotencyTtlHours: 72,
  currency: 'USD'
};
const MODULES = {"product": ["product_created", "product_updated", "product_research_requested"], "listing": ["listing_generation_requested", "listing_optimization_requested"], "order": ["order_created", "order_updated", "payment_failed", "order_cancelled", "order_delayed"], "inventory": ["inventory_updated", "low_inventory", "stockout_risk", "overstock_risk", "dead_stock_detected"], "pricing": ["price_check_requested", "competitor_price_changed", "margin_risk"], "customer": ["customer_created", "vip_customer_detected"], "support": ["customer_message", "customer_complaint"], "review": ["review_received", "negative_review_detected"], "returns": ["return_requested", "refund_requested", "exchange_requested", "return_risk"], "revenue": ["cart_abandoned", "checkout_abandoned", "customer_inactive", "repeat_purchase_opportunity"], "profit": ["profit_anomaly"], "analyst": ["sales_anomaly", "revenue_drop", "high_return_rate", "high_ad_spend"], "coo": ["daily_business_review", "weekly_business_review"], "exception": ["order_exception", "unknown_event"]};
const KNOWN = [].concat(...Object.values(MODULES));
const PII_KEYS = ['name','firstName','lastName','email','phone','address','shippingAddress','billingAddress','customerName','customerEmail','ip'];
const scrub = s => typeof s === 'string' ? s.replace(/[\w.+-]+@[\w-]+\.[\w.]+/g,'[email]').replace(/\+?\d[\d\s().-]{8,}\d/g,'[phone]') : s;
const redact = o => Array.isArray(o) ? o.map(redact) : (o && typeof o === 'object') ? Object.fromEntries(Object.entries(o).filter(([k]) => !PII_KEYS.includes(k)).map(([k,v]) => [k, redact(v)])) : scrub(o);
try {
  const j = $json;
  const raw = (j.body && typeof j.body === 'object') ? j.body : j;
  const hdr = j.headers || {};
  const src = String(raw.source || hdr['x-source'] || 'generic').toLowerCase();
  const TOPICS = {'orders/create':'order_created','orders/updated':'order_updated','orders/cancelled':'order_cancelled','products/create':'product_created','products/update':'product_updated','customers/create':'customer_created','refunds/create':'refund_requested','inventory_levels/update':'inventory_updated','checkouts/create':'checkout_abandoned','ORDER_CHANGE':'order_updated','ANY_OFFER_CHANGED':'competitor_price_changed','LISTINGS_ITEM_STATUS_CHANGE':'product_updated','ORDER.CREATED':'order_created','ORDER.CANCELLED':'order_cancelled','ITEM.SOLD':'order_created','RETURN.CREATED':'return_requested'};
  const topic = raw.topic || raw.notificationType || hdr['x-shopify-topic'];
  let eventType = String(raw.eventType || TOPICS[topic] || '').trim();
  const errors = [];
  if (!eventType) errors.push('missing eventType');
  else if (!KNOWN.includes(eventType)) errors.push('unrecognised eventType: ' + eventType);
  if (errors.length) eventType = 'unknown_event';
  const p = (raw.payload && typeof raw.payload === 'object') ? raw.payload : raw;
  const pick = (...keys) => { for (const k of keys) { const v = p[k] !== undefined ? p[k] : raw[k]; if (v !== undefined && v !== null && v !== '' && typeof v !== 'object') return String(v); } return ''; };
  const ts = String(raw.timestamp || new Date().toISOString());
  const customerId = pick('customerId','customer_id') || (p.customer && p.customer.id ? String(p.customer.id) : '');
  const orderId = pick('orderId','order_id','AmazonOrderId') || (eventType.startsWith('order') ? pick('id') : '');
  const productId = pick('productId','product_id','asin','itemId');
  const sku = pick('sku','SKU','sellerSku');
  const hookId = hdr['x-shopify-event-id'] || hdr['x-shopify-webhook-id'] || '';
  const eventId = String(raw.eventId || hookId || ['evt', src, eventType, orderId || productId || customerId || sku || 'na', ts].join('-')).replace(/\s+/g, '');
  // ---- idempotency (replace static data with a DB table / Redis in production)
  const sd = $getWorkflowStaticData('global');
  sd.seen = sd.seen || {};
  const now = Date.now(), ttl = CONFIG.idempotencyTtlHours * 3600000;
  for (const k of Object.keys(sd.seen)) if (now - sd.seen[k] > ttl) delete sd.seen[k];
  const isDuplicate = !!sd.seen[eventId] && !(raw.metadata && raw.metadata.allowDuplicate);
  if (!isDuplicate) sd.seen[eventId] = now;
  const event = {eventId, eventType, source: src, timestamp: ts, customerId, orderId, productId, sku, payload: p,
    metadata: {...(raw.metadata || {}), depth: Number((raw.metadata && raw.metadata.depth) || 0), receivedAt: new Date().toISOString(), validationErrors: errors}};
  const exceptions = errors.length ? [{type:'VALIDATION', severity:'LOW', source:'MASTER - Normalize Event', message: errors.join('; ')}] : [];
  return {json:{event, aiSafe: redact(event), config: CONFIG, isDuplicate, exceptions}};
} catch (err) {
  const event = {eventId:'evt-err-' + Date.now(), eventType:'unknown_event', source:'unknown', timestamp:new Date().toISOString(), customerId:'', orderId:'', productId:'', sku:'', payload:{}, metadata:{depth:0, validationErrors:[String(err && err.message)]}};
  return {json:{event, aiSafe:event, config:CONFIG, isDuplicate:false, exceptions:[{type:'NORMALIZATION_FAILURE', severity:'HIGH', source:'MASTER - Normalize Event', message:String(err && err.message), recommendedAction:'Inspect the inbound payload'}]}};
}

