 customersAtRisk:[{customerId:'C-2004', note:'8 orders, 4 returns, 2 complaints, inactive 160 days'},{customerId:'C-2002', note:'VIP customer with a support ticket open over 24h'}]
};
const PII_KEYS = ['name','firstName','lastName','email','phone','address','shippingAddress','billingAddress','customerName','customerEmail','ip'];
const scrub = s => typeof s === 'string' ? s.replace(/[\w.+-]+@[\w-]+\.[\w.]+/g,'[email]').replace(/\+?\d[\d\s().-]{8,}\d/g,'[phone]') : s;
const redact = o => Array.isArray(o) ? o.map(redact) : (o && typeof o === 'object') ? Object.fromEntries(Object.entries(o).filter(([k]) => !PII_KEYS.includes(k)).map(([k,v]) => [k, redact(v)])) : scrub(o);
const prods = Object.values(DB.products);
const msg = (e.payload && typeof e.payload.message === 'string') ? e.payload.message : '';
