const AGENT = "Product Intelligence", TASK = "Analyse product opportunity: demand, competition, price, estimated margin, reviews, weaknesses, risks. Give an opportunityScore 0-100 and a recommendation (PURSUE, TEST_SMALL, PASS or NEED_MORE_DATA).";
const r2 = x => Math.round(x * 100) / 100;
try {
const e = $json.event, c = $json.context || {}, cfg = $json.config;
let followUps = [];
const pr = c.product || {}, p = e.payload || {};
const price = Number(p.price ?? pr.price ?? 0), cost = Number(p.estimatedCost ?? pr.cost ?? 0);
const ship = Number(p.shippingCost ?? pr.shippingCost ?? 0);
const fees = price * 0.179 + 0.3 + ship;
const margin = price > 0 ? r2((price - cost - fees) / price) : 0;
const demand = Number(p.monthlySearchVolume || 0), comp = Number(p.competitorCount || 0);
const missing = [];
if (!price) missing.push('price'); if (!cost) missing.push('cost'); if (!demand) missing.push('demand data');
const score = Math.max(0, Math.min(100, Math.round(40 + margin * 100 + (demand > 5000 ? 15 : demand > 1000 ? 8 : 0) - (comp > 100 ? 20 : comp > 30 ? 10 : 0) - missing.length * 8)));
const risks = [];
if (price && margin < 0.15) risks.push('Thin margin'); if (comp > 100) risks.push('Highly competitive niche'); if (missing.length) risks.push('Missing data: ' + missing.join(', '));
const heur = {productId: e.productId || pr.productId || '', opportunityScore: score,
  demandAssessment: demand ? (demand > 5000 ? 'HIGH' : demand > 1000 ? 'MEDIUM' : 'LOW') : 'UNKNOWN',
  competitionAssessment: comp ? (comp > 100 ? 'HIGH' : comp > 30 ? 'MEDIUM' : 'LOW') : 'UNKNOWN',
  estimatedMargin: margin, risks,
  recommendation: missing.length >= 2 ? 'NEED_MORE_DATA' : score >= 65 ? 'PURSUE' : score >= 45 ? 'TEST_SMALL' : 'PASS',
  reason: 'Estimated margin ' + Math.round(margin * 100) + '% after marketplace, payment and shipping costs; score ' + score + '.',
  confidence: missing.length >= 2 ? 0.35 : missing.length ? 0.55 : 0.75};
const KEYS = Object.keys(heur);
const sys = 'You are the ' + AGENT + ' of an ecommerce operations system. TASK: ' + TASK + ' Respond with ONE JSON object containing exactly these keys: ' + KEYS.join(', ') + '. Use ONLY the supplied data. Never invent order, customer, price, inventory or review facts. If data is missing, set confidence below 0.5 and explain in the reason. Confidence is a number from 0 to 1. Output raw JSON only, no markdown.';
return {json:{...$json, agent:AGENT, moduleOutput:heur, schemaKeys:KEYS, agentError:null, followUpEvents:followUps,
  aiRequest:{model:cfg.aiModel, temperature:0.1, response_format:{type:'json_object'}, messages:[{role:'system', content:sys},{role:'user', content:JSON.stringify({event:$json.aiSafe, context:$json.aiSafeContext, deterministicBaseline:heur})}]}}};
} catch (err) {
  const m = String(err && err.message || err);
  return {json:{...$json, agent:AGENT, moduleOutput:null, agentError:m, exceptions:[...($json.exceptions || []), {type:'AGENT_FAILURE', severity:'HIGH', source:AGENT, message:AGENT + ' failed: ' + m, recommendedAction:'Inspect agent node and input data'}]}};
}

