  seo: {metaTitle: base.slice(0, 60), metaDescription: (base + ' - ' + (feats[0] || '')).slice(0, 155)},
  optimizationSuggestions: miss.map(m => 'Provide ' + m), confidence: miss.length ? 0.5 : 0.72};
const KEYS = Object.keys(heur);
const sys = 'You are the ' + AGENT + ' of an ecommerce operations system. TASK: ' + TASK + ' Respond with ONE JSON object containing exactly these keys: ' + KEYS.join(', ') + '. Use ONLY the supplied data. Never invent order, customer, price, inventory or review facts. If data is missing, set confidence below 0.5 and explain in the reason. Confidence is a number from 0 to 1. Output raw JSON only, no markdown.';
